/**
 * Comprehensive stock catalog — static data, no API calls.
 * Covers: full S&P 500 (503), Nasdaq 100 extras, Dow 30, major ETFs, major ADRs,
 * and a selection of well-known US mid-caps.
 *
 * Each entry: ticker, name, exchange, sector (GICS short), indices membership.
 * Prices are never stored here — fetch on demand via the quote API.
 *
 * Source notes:
 *  - S&P 500 constituents as of 2025-Q2 (update after quarterly rebalances)
 *  - Nasdaq 100 as of 2025-Q2
 *  - ETF list: iShares, Vanguard, SPDR, ARK, Invesco confirmed as of 2025
 *  - ADRs: only well-known, liquid names included; no obscure OTC tickers
 */

export interface CatalogEntry {
  ticker:   string;
  name:     string;
  exchange: "NYSE" | "NASDAQ" | "AMEX" | "SET" | "OTC" | "CBOE";
  sector:   string;   // GICS short form
  indices:  string[]; // e.g. ["SP500", "NASDAQ100", "DOW30"]
}

