// ─── Build lookup map ─────────────────────────────────────────────────────────

export const CATALOG: ReadonlyMap<string, CatalogEntry> = new Map(
  _entries
    .filter(([ticker]) => ticker.length > 0)
    .map(([ticker, info]) => [ticker, { ticker, ...info }] as const)
);

// ─── Index sets for browse ────────────────────────────────────────────────────

export const INDEX_LABELS: Record<string, string> = {
  SP500:    "S&P 500",
  NASDAQ100:"Nasdaq 100",
  DOW30:    "Dow Jones 30",
  ETF:      "ETFs",
  ADR:      "ADRs / Global",
};

export const SECTOR_LABELS: Record<string, string> = {
  Tech:     "Information Technology",
  Finance:  "Financials",
  Health:   "Health Care",
  Consumer: "Consumer Discretionary",
  Staples:  "Consumer Staples",
  Comm:     "Communication Services",
  Energy:   "Energy",
  Indust:   "Industrials",
  Matls:    "Materials",
  RealEst:  "Real Estate",
  Utility:  "Utilities",
  ETF:      "ETFs & Funds",
};

// All sectors, ordered
export const ALL_SECTOR_KEYS = Object.keys(SECTOR_LABELS);

// Get all entries for an index
export function getByIndex(index: string): CatalogEntry[] {
  const out: CatalogEntry[] = [];
  for (const entry of CATALOG.values()) {
    if (entry.indices.includes(index)) out.push(entry);
  }
  return out.sort((a, b) => a.ticker.localeCompare(b.ticker));
}

// Get all entries for a sector
export function getBySector(sector: string): CatalogEntry[] {
  const out: CatalogEntry[] = [];
  for (const entry of CATALOG.values()) {
    if (entry.sector === sector) out.push(entry);
  }
  return out.sort((a, b) => a.ticker.localeCompare(b.ticker));
}

// Search: returns up to `limit` matches ranked by relevance
export function searchCatalog(query: string, limit = 20): CatalogEntry[] {
  if (!query.trim()) return [];
  const upper = query.toUpperCase();

  const scored: { entry: CatalogEntry; score: number }[] = [];
  for (const entry of CATALOG.values()) {
    const t = entry.ticker.toUpperCase();
    const n = entry.name.toUpperCase();
    let score: number | null = null;

    if (t === upper)                           score = 0;
    else if (t.startsWith(upper))              score = 1;
    else if (n.startsWith(upper))              score = 2;
    else if (n.includes(upper) && upper.length >= 2) score = 3;

    if (score !== null) scored.push({ entry, score });
  }

  return scored
    .sort((a, b) => a.score - b.score || a.entry.ticker.localeCompare(b.entry.ticker))
    .slice(0, limit)
    .map(x => x.entry);
}

export const CATALOG_SIZE = _entries.length;
